(function(){'use strict';async function j(p){const r=await fetch(p);if(!r.ok)throw Error(p);return r.json()}function cards(products,longTerm){const out={};for(const[id,p]of Object.entries(products.cards||{})){const lt=longTerm.cards[id];out[id]={key:id,name:p.name,issuer:p.issuer,article:p.article_url,applicationUrl:p.application_url,annualFee:lt.annual_fee,q7:(lt.q7||[]).map(x=>({id:x.id,label:x.label,annualValue:x.annual_value,short:x.short})),q8:(lt.q8||[]).map(x=>({id:x.id,label:x.label,short:x.short}))}}return out}async function start(){try{const m=await j('data/runtime-manifest.json'),k=['bank_rules','bank_rule_predicates','offer_timing','approval','long_term','orchestrator','report_templates','products','questions','fact_mapping'],v=await Promise.all(k.map(x=>j(m[x].path))),[rules,predicates,timing,approval,longTerm,orchestrator,reportTemplates,products,questions,factMapping]=v,c=cards(products,longTerm);window.NB_CONFIG={snapshotDate:m.bank_rules.snapshot,engineVersion:'runtime-3',cards:c};window.NBRuntime={manifest:m,rules,predicates,timing,approval,longTerm,orchestrator,reportTemplates,products,questions,factMapping};TimingAdapter.hydrate(c,timing);window.NBEngine={evaluate:AssessmentRuntimeEngineV3.evaluate,normalizeAssessmentFacts:(id,a)=>FactNormalizerV3.normalize(id,a,factMapping),runtimeEngineVersion:AssessmentRuntimeEngineV3.version};window.dispatchEvent(new Event('nb-runtime-ready'))}catch(e){console.error(e);const x=document.getElementById('main');if(x)x.innerHTML='<div class="hero"><h2>运行数据加载失败，无法进行评估。</h2></div>'}}start()})();
